// SmartHelmet/Software/src/App.jsx

import { useState } from 'react';
import SplashScreen from './components/SplashScreen';
import Dashboard from './pages/Dashboard';
import './styles/global.css';

const TRANSITION_MS = 900; // must match CSS exit animation duration

function App() {
  const [phase, setPhase] = useState('splash'); // splash | loading | exiting | dashboard

  const handleLaunch = () => {
    setPhase('loading');
    setTimeout(() => {
      setPhase('exiting');
      setTimeout(() => setPhase('dashboard'), TRANSITION_MS);
    }, 2000); // 2-second loading phase to preload dashboard in background
  };

  return (
    <>
      {(phase === 'loading' || phase === 'exiting' || phase === 'dashboard') && (
        <div className="dashboard-enter">
          <Dashboard />
        </div>
      )}
      {phase !== 'dashboard' && (
        <SplashScreen
          onLaunch={handleLaunch}
          exiting={phase === 'exiting'}
          isLoading={phase === 'loading'}
        />
      )}
    </>
  );
}

export default App;
